from typing import List
from rosterkit.models import Mark, Student
from rosterkit.attendance import days_missed

# ---
def absence_notice(
    student: Student, marks: List[Mark]
) -> str:
    """Parent-facing text listing each absent day."""
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError(
                f"mark for {mark.student_id} is not for "
                f"{student.student_id}"
            )
    missed = days_missed(marks)
    if not missed:
        raise ValueError(
            f"no absences for {student.student_id}"
        )
    dates = ", ".join(stamp.isoformat() for stamp in missed)
    count = len(missed)
    unit = "day" if count == 1 else "days"
    name = f"{student.first_name} {student.last_name}"
    return (
        f"Dear parent or guardian, {name} missed "
        f"{count} {unit} of class: {dates}."
    )
